 1	export interface PromptBuilderConfig {
 2	  identity: string;
 3	  domainContext?: string;
 4	  responseGuidelines?: string;
 5	  toolPreamble?: string;
 6	}
 7	
 8	export interface PromptBuilderOptions {
 9	  toolInstructions?: string[];
10	  additionalContext?: string;
11	}
12	
13	const DEFAULT_TOOL_PREAMBLE = `When users ask questions that relate to available tools, USE THE PROVIDED TOOLS to get accurate, real-time information.
14	
15	IMPORTANT:
16	- Always use tools for specific data rather than guessing.
17	- If a tool call fails, explain the error and offer alternatives.
18	- Combine tool results with your knowledge to provide comprehensive answers.
19	
20	CLARIFICATION RULE: If you are unsure which filter to apply or how to interpret the user's request, ASK the user for clarification BEFORE calling the tool.
21	When a question is clear and maps directly to known filters, proceed without asking.`;
22	
23	export class PromptBuilder {
24	  constructor(private readonly config: PromptBuilderConfig) {}
25	
26	  build(options: PromptBuilderOptions = {}): string {
27	    const {toolInstructions, additionalContext} = options;
28	    const parts: string[] = [this.config.identity];
29	
30	    if (this.config.domainContext) {
31	      parts.push(this.config.domainContext);
32	    }
33	
34	    if (toolInstructions?.length) {
35	      const preamble = this.config.toolPreamble ?? DEFAULT_TOOL_PREAMBLE;
36	      const numbered = toolInstructions.map((instruction, i) => `${i + 1}. ${instruction}`).join('\n\n');
37	      parts.push(`${preamble}\n\n${numbered}`);
38	    }
39	
40	    if (this.config.responseGuidelines) {
41	      parts.push(`Response Guidelines:\n${this.config.responseGuidelines}`);
42	    }
43	
44	    if (additionalContext) {
45	      parts.push(`Additional Context:\n${additionalContext}`);
46	    }
47	
48	    return parts.join('\n\n');
49	  }
50	}

